eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   textData: () => (/* binding */ textData)\n/* harmony export */ });\nconst textData = {\n    landPage: {\n        heading: \"SCHLAGERPUNKARNA\",\n        paragraph: \"Fyra musikanter som delar ett gemensamt m\\xe5l, att sprida det schlanarkistiska manifestet.\"\n    },\n    intro: {\n        heading: \"L\\xc5T SCHLANARKISMEN B\\xd6RJA!\",\n        paragraph: [\n            \"Underh\\xe5llning som allm\\xe4nheten ej kan motst\\xe5 att sjunga, skratta och dansa till. Schlanarkismen ska levas enligt f\\xf6ljande budord:\",\n            \"Du skall inga andra genrer hava j\\xe4mte schpunken.\",\n            \"Varje komposition skall inneh\\xe5lla MINST en tonartsh\\xf6jning.\",\n            \"Schlanarkism = Tonartsh\\xf6jningar OCH Anarkism.\",\n            \"Hellre ett sexpack Burgen i logen \\xe4n en flaska bubbel p\\xe5 krogen.\",\n            \"Den 27:e sm\\xe4ller det.\",\n            \"Volymer \\xe4r b\\xe4ttre \\xe4n album.\"\n        ]\n    },\n    characters: {\n        heading: \"CHOOSE YOUR PUNKARE\",\n        paragraph: \"L\\xe4r k\\xe4nna medlemmarna b\\xe4ttre!\",\n        punkare: [\n            {\n                name: \"Anarkist Book\",\n                role: \"S\\xe5ng\",\n                description: \"Schlanarkist? Javisst! St\\xe5r st\\xe4ndigt i frontlinjen med micken i hand och skriker slagord i hopp om att st\\xf6rta etablissemanget, en tonartsh\\xf6jning i taget. Fick smeknamnet Book n\\xe4r han l\\xe4ste klart das Kapital vid fyra \\xe5rs \\xe5lder. Ingen kan h\\xe5lla ig\\xe5ng publiken som Anarkist Book.\",\n                imgSrc: \"../punkare/pic-arvid.png\",\n                iconSrc: \"../icons/icon-instrument-mic.png\"\n            },\n            {\n                name: \"Per Prilla Wahlgren\",\n                role: \"Bas\",\n                description: \"Gillar l\\xe5ga frekvenser d\\xe5 dessa k\\xe4nns i hela kroppen trots bristande h\\xf6rsel. L\\xe4mnade Liding\\xf6 som sju\\xe5ring f\\xf6r att f\\xf6lja sin stora passion i livet j\\xe4mte musiken: Snuset. Hade en framg\\xe5ngsrik sejour som gatumusikant p\\xe5 S\\xf6dermalm men fick sv\\xe5rt med ekonomin vid sekelskiftet n\\xe4r mamma sa att han fick v\\xe4lja mellan veckopengen och snuset. Flyttade till Lund i samband med att Swedish Match \\xf6ppnade p\\xe5 Fiskaregatan.\",\n                imgSrc: \"../punkare/pic-emil.png\",\n                iconSrc: \"../icons/icon-instrument-bass.png\"\n            },\n            {\n                name: \"Roger Punkare\",\n                role: \"Gitarr\",\n                description: \"Spelar sexstr\\xe4ngad rosaglittrig elgitarr och gillar dist. Uppv\\xe4xt p\\xe5 fj\\xe4llet bland renar, mygg och japanska turister. Blev i tidig \\xe5lder en j\\xe4vel p\\xe5 att dricka hembr\\xe4nt och kokkaffe ur sin k\\xe5sa. Kan ibland ses i s\\xe4llskap av renar som lyssnar p\\xe5 hans snabba \\xe5ttondelar och horribla sk\\xe4mt. Gick p\\xe5 en mekanikf\\xf6rel\\xe4sning i fjol och l\\xe4rde sig att vinkeln mellan publik och scen spelar roll n\\xe4r man tenderar att slarva med underkl\\xe4der under morgonrocken. Har en kusin som sk\\xf6ter sn\\xf6r\\xf6jningen i Tomelilla.\",\n                imgSrc: \"../punkare/pic-edvin.png\",\n                iconSrc: \"../icons/icon-instrument-guitar.png\"\n            },\n            {\n                name: \"Carl-\\xd8la Sk\\xe4ggquizt\",\n                role: \"Trummor\",\n                description: \"Carl-\\xd8la \\xe4r ett Enigma. Ingen vet hur han l\\xe4rde sig spela trummor eller varf\\xf6r han har sv\\xe5rt att h\\xe5lla sig till ett spr\\xe5k. I intervjuer talar han d\\xe4remot alltid klarspr\\xe5k: “\\xe6 \\xf8 e p\\xf8lse er dejligt \\xe6\\xe6\\xe6\\xe6\\xe6\\xe6\\xe6”. \\xc4r oerh\\xf6rt svag f\\xf6r spandex. Har f\\xe5tt upp \\xf6gonen f\\xf6r bakning efter att han sprang p\\xe5 f\\xf6rfattaren till Sju sorters kakor under G\\xf6teborgsvarvet h\\xe4rom\\xe5ret.\",\n                imgSrc: \"../punkare/pic-tobias.png\",\n                iconSrc: \"../icons/icon-instrument-drums.png\"\n            }\n        ]\n    },\n    \"timeline\": {\n        \"heading\": \"DISKOGRAFI\",\n        \"paragraph\": \"Schlagerpunkarnas samlade musikskatt. 20 l\\xe5tar, minst 20 h\\xf6jningar.\",\n        \"discografi\": [\n            {\n                \"name\": \"Schlanarkismen f\\xf6ds\",\n                \"year\": \"2018\",\n                \"imgSrc\": \"shows/birth.png\",\n                \"description\": \"Anarkist \\xe4r milt berusad och l\\xe4ser ett flingpaket bakl\\xe4nges vilket resulterar i att det schlanarkistiska manifestet f\\xf6ds.\",\n                \"clickable\": false\n            },\n            {\n                \"name\": \"Vol. 1\",\n                \"year\": \"2019\",\n                \"imgSrc\": \"albums/pic-album1.png\",\n                \"description\": 'Schlagerpunkarnas f\\xf6rsta volym spelas in i Studio Sunk och tillg\\xe4ngligg\\xf6rs f\\xf6r allm\\xe4nheten. Blir en \"\\xf6ver-natten-succ\\xe9\".',\n                \"link\": \"https://open.spotify.com/album/6t608ghC7CqqUJYih2DrjM?si=ssJITkczRASioDX6dC00bg\",\n                \"songs\": [\n                    {\n                        \"number\": 1,\n                        \"title\": \"Gorom eld Svarten\",\n                        \"length\": \"3:48\"\n                    },\n                    {\n                        \"number\": 2,\n                        \"title\": \"Jag buger s\\xe5 bra\",\n                        \"length\": \"3:42\"\n                    },\n                    {\n                        \"number\": 3,\n                        \"title\": \"N\\xe5nting \\xe4r fel\",\n                        \"length\": \"4:02\"\n                    },\n                    {\n                        \"number\": 4,\n                        \"title\": \"La dolce vita\",\n                        \"length\": \"2:23\"\n                    },\n                    {\n                        \"number\": 5,\n                        \"title\": \"Evighet\",\n                        \"length\": \"3:36\"\n                    }\n                ],\n                \"clickable\": true\n            },\n            {\n                \"name\": \"Vol. 2\",\n                \"year\": \"2020\",\n                \"imgSrc\": \"albums/pic-album2.png\",\n                \"description\": \"Efter att allm\\xe4nheten b\\xf6nat och bett efter mer schlanarkism, sl\\xe4pper Schlagerpunkarna den efterl\\xe4ngtade uppf\\xf6ljaren till den f\\xf6rsta volymen. R\\xe5are och nyare \\xe4n den f\\xf6rsta.\",\n                \"link\": \"https://open.spotify.com/album/02uPMZPKU1TZzYanu9g52r?si=qAiPDROvQ52JH8vE-OHieg\",\n                \"songs\": [\n                    {\n                        \"number\": 1,\n                        \"title\": \"Hej Sofia\",\n                        \"length\": \"2:55\"\n                    },\n                    {\n                        \"number\": 2,\n                        \"title\": \"Manboy\",\n                        \"length\": \"2:46\"\n                    },\n                    {\n                        \"number\": 3,\n                        \"title\": \"Alla fickor\",\n                        \"length\": \"2:22\"\n                    },\n                    {\n                        \"number\": 4,\n                        \"title\": \"(Du \\xe4r s\\xe5) Yeah Yeah Wowow\",\n                        \"length\": \"2:48\"\n                    }\n                ],\n                \"clickable\": true\n            },\n            {\n                \"name\": \"Vol. 3\",\n                \"year\": \"2022\",\n                \"imgSrc\": \"albums/pic-album3.png\",\n                \"description\": \"Efter att ha l\\xe5tit schlanarkisterna sukta efter mer ett l\\xe4ngre tag sl\\xe4pps den tredje volymen samtidigt som Lundakarnevalen 2022 intr\\xe4ffar. Till karnevalisternas stora gl\\xe4dje.\",\n                \"link\": \"https://open.spotify.com/album/7iIsygKVwZeFmJgV4mvxzh?si=rw8xwKngQ2S-ktp-6CEHfQ\",\n                \"songs\": [\n                    {\n                        \"number\": 1,\n                        \"title\": \"Fingad \\xe4r en storrvind\",\n                        \"length\": \"3:42\"\n                    },\n                    {\n                        \"number\": 2,\n                        \"title\": \"2 Carame\",\n                        \"length\": \"3:00\"\n                    },\n                    {\n                        \"number\": 3,\n                        \"title\": \"Sun\",\n                        \"length\": \"2:28\"\n                    },\n                    {\n                        \"number\": 4,\n                        \"title\": \"Stay The Night\",\n                        \"length\": \"2:58\"\n                    },\n                    {\n                        \"number\": 5,\n                        \"title\": \"Michelangelo (7”)\",\n                        \"length\": \"2:18\"\n                    }\n                ],\n                \"clickable\": true\n            },\n            {\n                \"name\": \"Mellandagsr\\xf6j 1\",\n                \"year\": \"2022\",\n                \"imgSrc\": \"shows/mellandagsr\\xf6j2022.jpg\",\n                \"description\": \"En gemensam v\\xe4n h\\xf6r av sig med en id\\xe9 om att ta slut p\\xe5 kapitalismens h\\xf6gtid nummer ett, julen. Varde Mellandagsr\\xf6jet den 27e dec p\\xe5 Mejeriet i Lund!\",\n                \"clickable\": false\n            },\n            {\n                \"name\": \"Vol. 4\",\n                \"year\": \"2023\",\n                \"imgSrc\": \"albums/pic-album4.png\",\n                \"description\": \"Schlagerpunkarnas fj\\xe4rde volym, b\\xe4ttre \\xe4n allt som kommit tidigare, sl\\xe4pps den 27e dec. Samma dag som Mellandagsr\\xf6jet intr\\xe4ffar.\",\n                \"link\": \"https://open.spotify.com/album/3MKnI3nP3vck6LHGku0zVH?si=NflppymGRb29noQAxjsFyA\",\n                \"songs\": [\n                    {\n                        \"number\": 1,\n                        \"title\": \"Waterloo\",\n                        \"length\": \"3:12\"\n                    },\n                    {\n                        \"number\": 2,\n                        \"title\": \"Lyssna till ditt hj\\xe4rta\",\n                        \"length\": \"3:41\"\n                    },\n                    {\n                        \"number\": 3,\n                        \"title\": \"Tusen och en natt\",\n                        \"length\": \"3:21\"\n                    },\n                    {\n                        \"number\": 4,\n                        \"title\": \"Guld och gr\\xf6na skogar\",\n                        \"length\": \"4:13\"\n                    },\n                    {\n                        \"number\": 5,\n                        \"title\": \"Stad i ljus\",\n                        \"length\": \"3:58\"\n                    }\n                ],\n                \"clickable\": true\n            },\n            {\n                \"name\": \"Mellandagsr\\xf6j 2\",\n                \"year\": \"2023\",\n                \"imgSrc\": \"shows/mellandagsr\\xf6j2023.jpg\",\n                \"description\": \"Den 27:e sm\\xe4ller det (igen). Nu samtidigt som releasedagen av den tredje volymen. Mellandagsr\\xf6jet flyttas till den stora scenen f\\xf6r att anpassa lokalen f\\xf6r det enorma publikhavet. Och d\\xe4r har det stannat.\",\n                \"link\": \"https://www.youtube.com/watch?v=B1CgYt1It_M&t=3s\",\n                \"clickable\": false\n            },\n            {\n                \"name\": \"Mellandagsr\\xf6j 3 (Titelmatchen)\",\n                \"year\": \"2024\",\n                \"imgSrc\": \"shows/mellandagsr\\xf6j2024.jpg\",\n                \"description\": 'Efter att Anarkist spenderat majoriteten av 2024 med att krossa etablissemanget p\\xe5 annan ort utmanar Roger, Per-Prilla & Carl-\\xd8la honom till en titelmatch f\\xf6r att se om han fortfarande f\\xf6rtj\\xe4nar sin plats vid mikrofonen. Mellandagsr\\xf6jet 2024 utn\\xe4mndes d\\xe4rmed \"Titelmatchen\" och schlanarkisterna k\\xf6per ivrigt biljetter f\\xf6r att besk\\xe5da spektaklet. Men slutet gott, allting gott. Anarkist dyker upp och det bevisas att ingen kan ta hans plats.',\n                \"link\": \"https://www.youtube.com/watch?v=XC2IHm7WwUc\",\n                \"clickable\": false\n            },\n            {\n                \"name\": \"Vol. 5\",\n                \"year\": \"2025\",\n                \"imgSrc\": \"shows/future.png\",\n                \"description\": \"To be announced. Vad 2025 inneb\\xe4r f\\xf6r Schlagerpunkarna \\xe5terst\\xe5r att se. H\\xe5ll \\xf6gon (och \\xf6ron) \\xf6ppna.\",\n                \"clickable\": true\n            },\n            {\n                \"name\": \"Melodifestivalen\",\n                \"year\": \"2026\",\n                \"imgSrc\": \"shows/melodifestivalen.jpg\",\n                \"description\": \"Mellanakt i Mello? P\\xe5verka din lokala SVT-lobbyist och f\\xe5 det att h\\xe4nda!\",\n                \"clickable\": false\n            }\n        ]\n    },\n    reviews: {\n        heading: \"Maxade recentioner\",\n        paragraph: \"L\\xe4r k\\xe4nna medlemmarna b\\xe4ttre!\",\n        reviewer: [\n            {\n                name: \"Sarek\",\n                role: \"S\\xe5ngare\",\n                description: \"Schlagerpunkarna har gjort en helt fantastisk cover av Genom eld & vatten!\",\n                imgSrc: \"../reviews/pic-sarek.png\"\n            },\n            {\n                name: \"Student i AF-Borgen\",\n                role: \"Frackkl\\xe4dd\",\n                description: \"Kom igen nu Per-Prilla, k\\xf6r f\\xf6r FA-AN.\",\n                imgSrc: \"../reviews/pic-student.png\"\n            },\n            {\n                name: \"Christer Bj\\xf6rkman\",\n                role: \"TV-producent\",\n                description: \"N\\xe5n borde boka dem som mellanakt till Mello 2026\",\n                imgSrc: \"../reviews/pic-bj\\xf6rkman.png\"\n            }\n        ]\n    },\n    video: {\n        heading: \"FILMER\",\n        paragraph: \"Se punkarnas liveframtr\\xe4danden och musikvideor!\",\n        videos: [\n            {\n                name: \"Genom eld & vatten\",\n                genre: \"Musikvideo\",\n                description: \"\\uD83D\\uDCF8 Konrad Welinder & Jonathan Ahlstr\\xf6m\",\n                videoURL: \"https://www.youtube.com/embed/dMb8iliV0rI?si=no4Gd9-SVlZMktBl\",\n                imgSrc: \"\"\n            },\n            {\n                name: \"Hej Sofia\",\n                genre: \"Musikvideo\",\n                description: \"\\uD83D\\uDCF8 Konrad Welinder & Jonathan Ahlstr\\xf6m\",\n                videoURL: \"https://www.youtube.com/embed/G8jN-t282hc?si=gnR0NLBpvQ46acSf\",\n                imgSrc: \"\"\n            },\n            {\n                name: \"Mellandagsr\\xf6jet p\\xe5 mejeriet\",\n                genre: \"Liveframtr\\xe4dande\",\n                description: \"\\uD83D\\uDCF8 Jonathan Ahlstr\\xf6m\",\n                videoURL: \"https://www.youtube.com/embed/B1CgYt1It_M?si=FEu_-AfrF8iSgJm_\",\n                imgSrc: \"\"\n            }\n        ]\n    },\n    nameCollector: {\n        heading: \"Namninsamling\",\n        paragraph: \"Schlagerpunkarna borde f\\xe5 vara med i Melodifestivalen 2026. Skriv in ditt namn f\\xf6r att visa att du st\\xf6der schlanarkismens budskap.\"\n    },\n    footer: {\n        heading: \"SCHLAGERPUNKARNA\",\n        description: \"Anarkism och tonartsh\\xf6jningar sedan 2018.\",\n        paragraph: \"\",\n        links: {\n            facebook: \"https://www.facebook.com/yourpage\",\n            spotify: \"https://open.spotify.com/artist/yourartistid\",\n            youtube: \"https://www.youtube.com/channel/yourchannelid\",\n            instagram: \"https://www.instagram.com/yourprofile\"\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./app/lib/textData.ts\n");

